#!/usr/bin/env python3
"""Fast status summary that does not scan or lock the live SQLite database."""

from __future__ import annotations
import argparse, json, shutil
from datetime import datetime, timezone
from pathlib import Path


def main() -> int:
    p = argparse.ArgumentParser()
    p.add_argument("--database", required=True, type=Path)
    p.add_argument("--state-file", type=Path)
    p.add_argument("--screener-summary", type=Path)
    args = p.parse_args()
    db = args.database.expanduser().resolve()
    storage = shutil.disk_usage(db.parent)
    payload = {
        "observed_at": datetime.now(timezone.utc).isoformat(),
        "database": {
            "path": str(db),
            "exists": db.exists(),
            "bytes": db.stat().st_size if db.exists() else None,
            "wal_bytes": Path(str(db) + "-wal").stat().st_size
            if Path(str(db) + "-wal").exists()
            else 0,
            "modified_at": datetime.fromtimestamp(
                db.stat().st_mtime, timezone.utc
            ).isoformat()
            if db.exists()
            else None,
        },
        "filesystem": {
            "total_bytes": storage.total,
            "used_bytes": storage.used,
            "free_bytes": storage.free,
        },
        "auto_backfill_state": None,
        "screener": None,
    }
    if args.state_file and args.state_file.exists():
        payload["auto_backfill_state"] = json.loads(
            args.state_file.read_text(encoding="utf-8")
        )
    if args.screener_summary and args.screener_summary.exists():
        payload["screener"] = json.loads(
            args.screener_summary.read_text(encoding="utf-8")
        )
    print(json.dumps(payload, indent=2))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""Collect official NSE equity disclosures and XBRL fundamentals."""

import argparse
import json
import sys
from datetime import date, timedelta
from pathlib import Path

if __package__ in {None, ""}:
    sys.path.insert(0, str(Path(__file__).resolve().parents[1]))

from config.config import DATABASE_URL
from market_data.database import MarketDatabase
from market_data.disclosures import (
    BSEDisclosureClient,
    BSEDisclosureCollector,
    NSEDisclosureClient,
    NSEDisclosureCollector,
)


def parse_date(value):
    try:
        return date.fromisoformat(value)
    except ValueError as exc:
        raise argparse.ArgumentTypeError("Expected YYYY-MM-DD") from exc


def main(argv=None):
    parser = argparse.ArgumentParser(
        description="Collect NSE disclosures into the shared local SQLite database."
    )
    parser.add_argument(
        "--datasets",
        nargs="+",
        choices=NSEDisclosureCollector.DATASETS,
        default=list(NSEDisclosureCollector.DATASETS),
    )
    parser.add_argument("--exchange", choices=("nse", "bse", "all"), default="nse")
    parser.add_argument(
        "--bse-scrip-code", action="append", default=None,
        help="Limit BSE enrichment to one or more numeric scrip codes.",
    )
    parser.add_argument("--start-date", type=parse_date, default=date.today() - timedelta(days=30))
    parser.add_argument("--end-date", type=parse_date, default=date.today())
    parser.add_argument("--symbol")
    parser.add_argument("--database-url", default=DATABASE_URL)
    parser.add_argument("--window-days", type=int, default=30)
    parser.add_argument("--timeout", type=float, default=30)
    parser.add_argument("--request-delay", type=float, default=0.75)
    parser.add_argument("--retries", type=int, default=3)
    parser.add_argument(
        "--skip-documents", action="store_true",
        help="Index filings without downloading linked XBRL/attachments.",
    )
    args = parser.parse_args(argv)
    if args.window_days < 1 or args.window_days > 90:
        parser.error("--window-days must be between 1 and 90")

    database = MarketDatabase(args.database_url)
    database.initialize()
    counts = {}
    if args.exchange in ("nse", "all"):
        client = NSEDisclosureClient(
            timeout=args.timeout, delay=args.request_delay, retries=args.retries
        )
        collector = NSEDisclosureCollector(
            database, client=client, fetch_documents=not args.skip_documents
        )
        try:
            counts["nse"] = collector.collect(
                args.start_date,
                args.end_date,
                datasets=args.datasets,
                symbol=args.symbol,
                window_days=args.window_days,
            )
        finally:
            client.session.close()
    if args.exchange in ("bse", "all"):
        bse_datasets = [
            item for item in args.datasets if item in BSEDisclosureCollector.DATASETS
        ]
        bse_client = BSEDisclosureClient(
            timeout=args.timeout, delay=args.request_delay
        )
        try:
            counts["bse"] = BSEDisclosureCollector(
                database, bse_client
            ).collect(
                bse_datasets,
                args.bse_scrip_code,
                start=args.start_date,
                end=args.end_date,
            )
        finally:
            bse_client.session.close()
    print(json.dumps(counts, sort_keys=True))
    failed = sum(
        value
        for exchange_counts in counts.values()
        for key, value in exchange_counts.items()
        if key.endswith("_failed")
    )
    return 1 if failed else 0


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
"""Generate chunked Git tree payloads for vendoring this repo into AARU.

The generated JSON files are directly consumable as ``tree_elements`` by the
GitHub create-tree API. Runtime data, caches, Git metadata and the generated
manifests themselves are excluded.
"""

from __future__ import annotations

import argparse
import json
from pathlib import Path
from typing import Dict, Iterable, List

EXCLUDED_PARTS = {
    ".git",
    ".venv",
    "venv",
    "__pycache__",
    ".pytest_cache",
    "vendor_manifests",
}
EXCLUDED_SUFFIXES = {".pyc", ".pyo", ".db", ".sqlite", ".sqlite3", ".wal", ".shm"}
EXCLUDED_PREFIXES = ("data/raw/", "data/databases/")


def included(path: Path, root: Path) -> bool:
    relative = path.relative_to(root).as_posix()
    if any(part in EXCLUDED_PARTS for part in path.relative_to(root).parts):
        return False
    if path.suffix.lower() in EXCLUDED_SUFFIXES:
        return False
    return not relative.startswith(EXCLUDED_PREFIXES)


def mode_for(path: Path) -> str:
    return "100755" if path.stat().st_mode & 0o111 else "100644"


def entries(root: Path, prefix: str) -> Iterable[Dict[str, str]]:
    for path in sorted(item for item in root.rglob("*") if item.is_file()):
        if not included(path, root):
            continue
        try:
            content = path.read_text(encoding="utf-8")
        except UnicodeDecodeError:
            raise SystemExit(f"Non-UTF-8 file requires explicit handling: {path}")
        yield {
            "path": f"{prefix}/{path.relative_to(root).as_posix()}",
            "mode": mode_for(path),
            "type": "blob",
            "content": content,
        }


def write_chunks(values: List[Dict[str, str]], output: Path, max_bytes: int) -> None:
    output.mkdir(parents=True, exist_ok=True)
    for old in output.glob("manifest_*.json"):
        old.unlink()
    chunks: List[List[Dict[str, str]]] = []
    current: List[Dict[str, str]] = []
    size = 2
    for value in values:
        encoded = json.dumps(value, ensure_ascii=False).encode("utf-8")
        if current and size + len(encoded) + 2 > max_bytes:
            chunks.append(current)
            current = []
            size = 2
        current.append(value)
        size += len(encoded) + 1
    if current:
        chunks.append(current)
    for index, chunk in enumerate(chunks, 1):
        (output / f"manifest_{index:03d}.json").write_text(
            json.dumps(chunk, ensure_ascii=False, indent=2) + "\n",
            encoding="utf-8",
        )
    (output / "index.json").write_text(
        json.dumps(
            {
                "schema": "aaru.vendor-manifest-index.v1",
                "source_commit": "GENERATED_AT_COMMIT",
                "prefix": values[0]["path"].split("/upstream/")[0] + "/upstream" if values else "",
                "files": len(values),
                "chunks": len(chunks),
                "chunk_files": [f"manifest_{i:03d}.json" for i in range(1, len(chunks) + 1)],
            },
            indent=2,
        ) + "\n",
        encoding="utf-8",
    )


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--root", type=Path, default=Path(__file__).resolve().parents[1])
    parser.add_argument("--output", type=Path, default=Path("vendor_manifests"))
    parser.add_argument("--prefix", default="tools/aaru_market_data/upstream")
    parser.add_argument("--max-bytes", type=int, default=85000)
    args = parser.parse_args()
    values = list(entries(args.root.resolve(), args.prefix.rstrip("/")))
    write_chunks(values, args.output, args.max_bytes)
    print(json.dumps({"files": len(values), "output": str(args.output)}, sort_keys=True))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
